#!/usr/bin/env bash
# maps — clj/bb test suite (ADR-2606160842 py->clj port wave; Python methods pruned).
# Self-contained: requires the namespaces directly rather than the removed bb.edn
# `test:maps` task (bb.edn deleted by ADR-2607173000; this inlines that task's exact
# body — same pattern as credits/karakuri/shomei/suji's own run_tests.sh).
set -euo pipefail
cd "$(dirname "$0")/../.."
exec bb -e '(require (quote clojure.test) (quote maps.tests.test-analyze) (quote maps.tests.test-ingest) (quote maps.tests.test-chunk) (quote maps.tests.test-search) (quote maps.tests.test-reverse) (quote maps.tests.test-transit) (quote maps.tests.test-verify) (quote maps.tests.test-onsen) (quote maps.methods.test-ingest-json) (quote maps.methods.test-maps3d-bpmn) (quote maps.methods.test-maps3d-bpmn-fidelity) (quote maps.methods.test-maps3d-net-tasks) (quote maps.methods.test-maps3d-persist) (quote maps.methods.test-maps3d-tasks) (quote maps.methods.test-e2e-http) (quote maps.methods.test-maps3d-net-http) (quote maps.methods.test-search) (quote maps.methods.test-transit))(let [r (clojure.test/run-tests (quote maps.tests.test-analyze) (quote maps.tests.test-ingest) (quote maps.tests.test-chunk) (quote maps.tests.test-search) (quote maps.tests.test-reverse) (quote maps.tests.test-transit) (quote maps.tests.test-verify) (quote maps.tests.test-onsen) (quote maps.methods.test-ingest-json) (quote maps.methods.test-maps3d-bpmn) (quote maps.methods.test-maps3d-bpmn-fidelity) (quote maps.methods.test-maps3d-net-tasks) (quote maps.methods.test-maps3d-persist) (quote maps.methods.test-maps3d-tasks) (quote maps.methods.test-e2e-http) (quote maps.methods.test-maps3d-net-http) (quote maps.methods.test-search) (quote maps.methods.test-transit))](System/exit (if (zero? (+ (:fail r) (:error r))) 0 1)))'
